    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        out = torch.empty_like(x)
        n = x.numel()
        chunks = (n + 15) // 16
        block_x = 256
        blocks_needed = (chunks + block_x - 1) // block_x
        grid_x = max(1, min(blocks_needed, 4096))  # capped grid; kernel grid-stride loop covers the rest
