            "sigmoid_forward",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[u64(x.data_ptr()), u64(out.data_ptr()), u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
